// The app has one command of its own -- `show_system_menu` -- and this is what
// gives it a name the capability file can grant.
//
// An app command is ACL-checked whenever the app ships a capability file, which
// this one does, so without this the frontend's `invoke("show_system_menu")`
// is refused: three letters of a permission short of a working system menu,
// with the reason only in the console. `commands` turns each name into an
// autogenerated `allow-*`/`deny-*` pair under `permissions/autogenerated`
// (gitignored: it is a build product, regenerated whenever a command changes).
fn main() {
    tauri_build::try_build(
        tauri_build::Attributes::new().app_manifest(
            tauri_build::AppManifest::new().commands(&["show_system_menu"]),
        ),
    )
    .expect("failed to run tauri-build")
}
